/* ============================================================
   DDIA Practice — flashcard deck
   218 cards spanning all twelve chapters.
   ============================================================ */

(function () {
  'use strict';

  window.FLASHCARDS = [
    /* ---------- Chapter 1: Reliability, Scalability, Maintainability ---------- */
    { id: 'faults-vs-failures', lesson: 'Ch 1', front: 'Fault vs. failure — what’s the difference?', back: 'A fault is one component misbehaving; a failure is the whole system stopping. Good systems tolerate faults so they never become failures.' },
    { id: 'tail-latency', lesson: 'Ch 1', front: 'Why does p99 (tail latency) matter more than the average?', back: 'Requests fan out into many backend calls — any slow call drags the whole page. Users live in the tail, and the slowest requests often come from the most valuable customers.' },
    { id: 'fan-out', lesson: 'Ch 1', front: 'What is fan-out?', back: 'One user request triggering many backend requests — e.g. reading a timeline that must fetch/merge tweets from many followees. High fan-out makes tail latency the user-visible latency.' },
    { id: 'chaos-monkey', lesson: 'Ch 1', front: 'Why deliberately inject faults (Chaos Monkey)?', back: 'Keeping the fault-tolerance machinery exercised and tested. If engineers are used to instance failures, they build services that survive them — and many critical bugs are poor error handling.' },
    { id: 'mttf-math', lesson: 'Ch 1', front: 'Disk MTTF is 10–50 years. What should a 10,000-disk cluster expect?', back: 'Roughly one disk death per day: 10,000 ÷ (10–50 years × 365) ≈ 0.5–2.7. Fleet size, not per-disk quality, sets the failure rate.' },
    { id: 'slo-sla', lesson: 'Ch 1', front: 'SLO vs. SLA?', back: 'An SLO is the expected performance/availability target (e.g. median < 200 ms, p99 < 1 s, up ≥ 99.9%). An SLA is its contractual twin — the version customers can demand refunds for.' },

    /* ---------- Chapter 2: Data Models and Query Languages ---------- */
    { id: 'codd-1970', lesson: 'Ch 2', front: 'Codd’s relational model (1970) — what is it, in one breath?', back: 'Data organized into relations (tables), each an unordered collection of tuples (rows) — hiding the internal representation behind a clean interface. Dominant since the mid-1980s.' },
    { id: 'nosql-forces', lesson: 'Ch 2', front: 'The four driving forces behind NoSQL adoption?', back: 'Greater scalability than relational DBs; free/open-source preference; specialized query operations; frustration with restrictive relational schemas.' },
    { id: 'polyglot-persistence', lesson: 'Ch 2', front: 'What is polyglot persistence?', back: 'Relational and nonrelational datastores used side by side, each where it fits — not one winner.' },
    { id: 'impedance-mismatch', lesson: 'Ch 2', front: 'The object-relational “impedance mismatch”?', back: 'The disconnect between object-oriented application code and relational tables/rows/columns (term from electronics). ORMs like ActiveRecord and Hibernate reduce boilerplate but can’t hide the difference.' },
    { id: 'shredding', lesson: 'Ch 2', front: 'What is shredding, in relational modeling?', back: 'Splitting a document-like structure (a résumé) into multiple tables (positions, education, contact_info) — leading to cumbersome schemas when the data is naturally a tree.' },
    { id: 'document-locality', lesson: 'Ch 2', front: 'Document locality — the win and the two limits?', back: 'The whole document loads in one read. Limits: the DB loads the entire document even for a small part, and any update that changes encoded size rewrites the whole document. Keep documents small.' },
    { id: 'codasyl-access-paths', lesson: 'Ch 2', front: 'CODASYL network model — why was it painful?', back: 'Records could have multiple parents, linked by pointer-like chains; the only way to reach data was traversing hand-picked access paths with a cursor — like navigating an n-dimensional data space. Schema changes meant rewriting query code.' },
    { id: 'query-optimizer-win', lesson: 'Ch 2', front: 'Why did the relational model beat CODASYL, structurally?', back: 'Access paths didn’t vanish — they moved into the query optimizer, chosen automatically. Build the optimizer once and every application benefits; new query patterns need a new index, not new code.' },
    { id: 'schema-flexibility', lesson: 'Ch 2', front: 'Schema-on-read vs. schema-on-write?', back: 'On-write: explicit schema enforced at write time (like static type checking). On-read: implicit structure interpreted at read time (like dynamic typing). “Schemaless” data still has an implicit schema.' },
    { id: 'declarative-vs-imperative', lesson: 'Ch 2', front: 'Why do declarative query languages parallelize better?', back: 'They specify only the pattern of results, not the algorithm — so the database can run them across cores and machines. Imperative code pins operations to an order.' },
    { id: 'mapreduce-pure-functions', lesson: 'Ch 2', front: 'Why must MapReduce map/reduce functions be pure?', back: 'No side effects, no extra queries, inputs only — so the framework can run them anywhere, in any order, and re-run them on failure. Purity is what makes distribution and retries safe.' },
    { id: 'nosql-reinvents-sql', lesson: 'Ch 2', front: 'MongoDB’s aggregation pipeline (2.2) demonstrated what?', back: 'That a NoSQL system may find itself accidentally reinventing SQL, albeit in disguise — the pipeline is as expressive as a subset of SQL, in JSON syntax.' },
    { id: 'property-graph-model', lesson: 'Ch 2', front: 'The property graph model — what’s in a vertex and an edge?', back: 'Vertex: unique ID, outgoing edges, incoming edges, properties. Edge: unique ID, tail vertex, head vertex, label, properties. Think: two relational tables with indexes on both tail and head.' },
    { id: 'cypher-variable-paths', lesson: 'Ch 2', front: 'What does Cypher’s WITHIN*0.. express?', back: 'A variable-length path — follow a WITHIN edge zero or more times, like * in a regex — because you don’t know how many levels separate a city from the continent. SQL needs WITH RECURSIVE (29 lines vs 4).' },
    { id: 'triple-store-model', lesson: 'Ch 2', front: 'The triple-store data model?', back: 'Everything as (subject, predicate, object). Object is either a primitive value (then it’s a property on the subject-vertex) or another vertex (then the predicate is an edge).' },
    { id: 'datalog-rules', lesson: 'Ch 2', front: 'What makes Datalog different from Cypher/SPARQL?', back: 'Queries are rules that derive new predicates from data and other rules — composable and reusable like functions. Less convenient for one-off queries, powerful for complex data. The 1980s foundation of the others.' },

    /* ---------- Chapter 3: Storage and Retrieval ---------- */
    { id: 'log-def', lesson: 'Ch 3', front: 'What is a log, in the storage-engine sense?', back: 'An append-only sequence of records — not application logs, possibly binary. Appending is fast; finding anything in it is O(n), which is what indexes fix.' },
    { id: 'index-tradeoff', lesson: 'Ch 3', front: 'The fundamental index trade-off?', back: 'Indexes speed up reads but every index slows down writes — each write must update every index. That’s why databases don’t index everything by default: you pick per query pattern.' },
    { id: 'bitcask', lesson: 'Ch 3', front: 'Bitcask (Riak’s engine) — how it works, and its constraint?', back: 'An in-memory hash map of every key → byte offset in an append-only data file; one disk seek per read. Constraint: all keys must fit in memory; and no range queries.' },
    { id: 'compaction-segments', lesson: 'Ch 3', front: 'What do compaction and segment merging do?', back: 'Break the log into size-capped segments; compaction discards duplicate keys keeping the most recent value; merging combines segments — in the background, since written segments are immutable.' },
    { id: 'sstable-format', lesson: 'Ch 3', front: 'SSTable — the format and its three advantages?', back: 'A segment sorted by key, each key once. (1) Merging is mergesort; (2) the in-memory index can be sparse; (3) blocks of records can be compressed.' },
    { id: 'sparse-index', lesson: 'Ch 3', front: 'Why can an SSTable’s in-memory index be sparse?', back: 'Sorted order means any key must lie between its indexed neighbors — looking for “handiwork” between indexed “handbag” and “handsome”, jump to handbag’s offset and scan a few KB. One entry per few kilobytes suffices.' },
    { id: 'memtable', lesson: 'Ch 3', front: 'What is a memtable, and what protects it?', back: 'The in-memory sorted tree (red-black/AVL) that receives writes, flushed to disk as an SSTable at a threshold. A separate unsorted log on disk restores it after a crash — discarded once flushed.' },
    { id: 'compaction-strategies', lesson: 'Ch 3', front: 'Size-tiered vs. leveled compaction?', back: 'Size-tiered (HBase): merge newer/smaller SSTables into older/larger ones. Leveled (LevelDB, RocksDB): split key ranges into smaller SSTables across “levels” — more incremental, less disk space. Cassandra does both.' },
    { id: 'branching-factor', lesson: 'Ch 3', front: 'B-tree branching factor, and what does 4 levels buy?', back: 'The number of child-page references per page — typically several hundred. 4 KB pages × factor 500, four levels deep: up to 256 TB. Most databases fit in 3–4 levels.' },
    { id: 'write-amplification', lesson: 'Ch 3', front: 'Write amplification — define it. Who suffers more, B-trees or LSM-trees?', back: 'One database write becoming multiple disk writes over its lifetime. B-trees suffer more: every datum written at least twice (WAL + page), plus whole-page rewrites for tiny changes — an SSD-wear concern.' },
    { id: 'latches', lesson: 'Ch 3', front: 'What are latches in a B-tree, and why do LSM engines need less locking?', back: 'Lightweight locks protecting tree structures so threads never see half-updated state. LSM engines merge in the background and swap segments atomically — much simpler.' },
    { id: 'heap-file', lesson: 'Ch 3', front: 'What is a heap file?', back: 'Unordered row storage that indexes point into — avoiding duplication when multiple secondary indexes exist. In-place update works if the value fits; otherwise move it and leave a forwarding pointer.' },
    { id: 'clustered-vs-covering', lesson: 'Ch 3', front: 'Clustered vs. covering index?', back: 'Clustered: the entire row lives inside the index (InnoDB primary keys). Covering: some columns stored in the index — enough that some queries never leave it (“it covers the query”).' },
    { id: 'concatenated-index', lesson: 'Ch 3', front: 'A concatenated index is like what paper artifact, and what’s its blind spot?', back: 'A phone book: (lastname, firstname) → number. Finds any lastname, or lastname+firstname — but is useless for firstname-only queries, because of the sort order.' },
    { id: 'oltp-vs-olap', lesson: 'Ch 3', front: 'OLTP vs. OLAP — the access patterns?', back: 'OLTP: small number of records fetched by key, random low-latency writes, end users, GB–TB. OLAP: aggregates over huge scans, bulk ETL writes, analysts, TB–PB; represents history rather than current state.' },
    { id: 'star-schema', lesson: 'Ch 3', front: 'The star schema — fact table, dimension tables, and the scale?', back: 'Each fact row is an event (purchase, click) with attributes and foreign keys into dimension tables (who/what/where/when). Fact tables at Apple/Walmart/eBay scale: tens of petabytes, 100+ columns.' },
    { id: 'bitmap-index', lesson: 'Ch 3', front: 'How does bitmap indexing evaluate WHERE clauses?', back: 'One bitmap per distinct value, one bit per row. IN (30, 68, 69) → bitwise OR of three bitmaps; = 31 AND store = 3 → bitwise AND. Valid because all columns share row order; RLE compresses sparse bitmaps.' },
    { id: 'vectorized-processing', lesson: 'Ch 3', front: 'What is vectorized processing?', back: 'Compressed column chunks that fit in the CPU’s L1 cache, iterated in tight loops with no function calls — bitwise operators work directly on compressed data, SIMD-friendly.' },
    { id: 'materialized-view', lesson: 'Ch 3', front: 'Materialized view vs. virtual view? And the data cube special case?', back: 'A materialized view writes query results to disk (a virtual view is just a query shortcut). A data cube is the dimension-grid special case — precomputed aggregates at the cost of flexibility (no non-dimension questions).' },
    { id: 'anti-caching', lesson: 'Ch 3', front: 'Anti-caching in in-memory databases?', back: 'Evict least-recently-used records to disk when memory runs out, reload on access — like OS swap but at record granularity. Indexes must still fit entirely in memory.' },
    { id: 'lsm-tree', lesson: 'Ch 3', front: 'LSM-tree — core idea in one breath', back: 'Append-only sorted logs (SSTables) merged by background compaction. Writes are always sequential → fast. Reads may hunt through levels (Cassandra, RocksDB, LevelDB).' },
    { id: 'b-tree', lesson: 'Ch 3', front: 'B-tree — core idea in one breath', back: 'Sorted fixed-size pages as a catalog tree. ~500 children per node → 4 levels reach 62.5B rows. Fast point lookups (Postgres, MySQL, SQLite, Oracle).' },
    { id: 'wal', lesson: 'Ch 3', front: 'What is a write-ahead log (WAL) for?', back: 'Crash safety: persist the intent on disk before mutating in-place pages. If you crash mid-change, replay the log — like leaving sticky notes before doing anything dangerous.' },
    { id: 'tombstone', lesson: 'Ch 3', front: 'Why doesn’t deleting data free space in Cassandra?', back: 'Deletes are tombstones — new writes that mark data dead. Space only returns when compaction merges levels and drops the dead entries.' },
    { id: 'bloom-filter', lesson: 'Ch 3', front: 'What does a Bloom filter tell you?', back: '“Definitely not here” (or “maybe here”). It lets an LSM read skip whole SSTables without touching disk — killing most of the read amplification.' },
    { id: 'column-store', lesson: 'Ch 3', front: 'Why are column stores (Redshift, Snowflake, BigQuery) fast for analytics?', back: 'Flip the database sideways: scans read only the needed columns → 10–30× less I/O, and same-type values sitting together compress beautifully.' },

    /* ---------- Chapter 4: Encoding and Evolution ---------- */
    { id: 'encoding-decoding', lesson: 'Ch 4', front: 'Encoding vs. decoding — definitions and aliases?', back: 'Encoding: in-memory → bytes (a.k.a. serialization, marshalling). Decoding: bytes → in-memory (parsing, deserialization, unmarshalling). “Encoding” avoids the transaction sense of “serialization”.' },
    { id: 'backward-compat', lesson: 'Ch 4', front: 'Backward compatibility — define it', back: 'Newer code can read data written by older code. Usually the easy direction: as the author of the new code, you know the old format.' },
    { id: 'forward-compat', lesson: 'Ch 4', front: 'Forward compatibility — define it, and why is it hard?', back: 'Older code can read data written by newer code. Hard because it requires old code to gracefully ignore additions made by newer versions.' },
    { id: 'rolling-upgrade', lesson: 'Ch 4', front: 'What is a rolling upgrade (staged rollout)?', back: 'Deploying a new version a few nodes at a time — no downtime, less risk (rollback before wide damage), more frequent releases. Requires old and new code to coexist.' },
    { id: 'builtin-serialization-risks', lesson: 'Ch 4', front: 'The four deep problems of language-specific serialization (pickle, Marshal, java.io.Serializable)?', back: 'Language lock-in; security holes (decoding instantiates arbitrary classes → RCE); versioning as an afterthought; efficiency as an afterthought.' },
    { id: 'json-2pow53', lesson: 'Ch 4', front: 'Why does Twitter’s API return tweet IDs as both a JSON number and a string?', back: 'Integers above 2^53 can’t be exactly represented in IEEE 754 doubles, so float-parsing languages like JavaScript mangle 64-bit IDs — the decimal string survives. JSON doesn’t distinguish integers from floats.' },
    { id: 'base64-33', lesson: 'Ch 4', front: 'What happens to binary data in JSON/XML, cost-wise?', back: 'No byte-string type, so binary data is Base64-encoded as text (schema marks it) — a somewhat hacky workaround that increases data size by 33%.' },
    { id: 'field-tags', lesson: 'Ch 4', front: 'Protobuf/Thrift field tags — the three rules?', back: 'Rename fields freely (bytes never contain names); never change a tag (instantly invalidates all data); never reuse a removed tag (old data still carries it and must stay ignorable).' },
    { id: 'varint', lesson: 'Ch 4', front: 'Variable-length integers (varints) — the ranges?', back: '–64…63 in one byte, –8192…8191 in two, and so on; the top bit of each byte signals more bytes. That’s how 1337 shrinks from 8 bytes to 2 (Thrift CompactProtocol, Protobuf, Avro).' },
    { id: 'avro-writer-reader', lesson: 'Ch 4', front: 'Avro: writer’s schema vs. reader’s schema?', back: 'The schema that encoded the data, and the schema the app expects — they need only be compatible: fields matched by name, unknown writer fields ignored, missing reader fields filled with defaults.' },
    { id: 'avro-evolution-rules', lesson: 'Ch 4', front: 'Avro schema evolution — the one rule?', back: 'You may only add or remove a field that has a default value (add without default breaks backward compat; remove without default breaks forward compat). Null requires a union type.' },
    { id: 'avro-schema-delivery', lesson: 'Ch 4', front: 'How does an Avro reader learn the writer’s schema? (3 contexts)', back: 'Big files: once at the head (object container files). Per-record databases: version number + schema-version database (Espresso). Network connections: negotiate at setup (Avro RPC).' },
    { id: 'dynamic-schemas', lesson: 'Ch 4', front: 'Why is Avro friendlier to dynamically generated schemas than Thrift/Protobuf?', back: 'No tag numbers: regenerate the schema whenever the source changes and fields still match by name. Tags would need careful hand-curation and could never be reused.' },
    { id: 'data-outlives-code', lesson: 'Ch 4', front: '“Data outlives code” — meaning and consequence?', back: 'Databases hold values written years ago in the original encoding, long after the code was replaced; rewriting is expensive. Schema evolution makes the store appear single-schema despite mixed historical versions.' },
    { id: 'location-transparency', lesson: 'Ch 4', front: 'Location transparency — definition and verdict?', back: 'RPC’s ambition: make a network request look like a local function call. Fundamentally flawed — network calls can be lost, time out (no knowledge!), need retries/idempotence, and have wild latency.' },
    { id: 'rest-vs-soap', lesson: 'Ch 4', front: 'REST vs. SOAP in one card?', back: 'REST: a design philosophy on HTTP — URLs as resources, HTTP for caching/auth/negotiation; experimentation-friendly (curl). SOAP: XML protocol + WS-* framework + WSDL codegen; interop pain, enterprise-only now.' },
    { id: 'rpc-timeout', lesson: 'Ch 4', front: 'What do you know when an RPC times out?', back: 'Nothing — the request may or may not have been processed; only the response is missing. Blind retries can perform the action twice, so idempotence belongs in the protocol.' },
    { id: 'broker-advantages', lesson: 'Ch 4', front: 'Five things a message broker buys you over direct RPC?', back: 'Buffers when recipients are down/overloaded; automatic redelivery after crashes; sender needs no recipient IP:port; one message to several recipients; logical decoupling of sender from recipient.' },
    { id: 'actor-model', lesson: 'Ch 4', front: 'The actor model — and why does it distribute better than RPC?', back: 'Concurrency via private-state actors processing async, possibly-lost messages one at a time. Location transparency works better because lossy async messages were already the in-process model — no local/remote mismatch to hide.' },

    /* ---------- Chapter 5: Replication ---------- */
    { id: 'sync-async-replication', lesson: 'Ch 5', front: 'Synchronous vs. asynchronous replication — the trade-off', back: 'Sync: followers guaranteed up-to-date, but writes stall if a follower dies. Async: fast, but acknowledged writes can be lost on leader failure. Semi-sync is the common compromise.' },
    { id: 'read-your-writes', lesson: 'Ch 5', front: 'Read-your-writes — the problem and a fix', back: 'User updates a profile, gets redirected, sees the old version (async replication lag hit a stale follower). Fix: route the user’s own reads to the leader, or track their update timestamp.' },
    { id: 'quorum', lesson: 'Ch 5', front: 'Why do quorums require w + r > n?', back: 'Read and write quorums must overlap, so at least one replica you read from has the newest value. Otherwise you can read a stale copy with no way to know.' },
    { id: 'leader-follower-flow', lesson: 'Ch 5', front: 'Leader-based replication — the three-step dance', back: '(1) Clients send all writes to the leader, which writes to local storage first. (2) The leader sends each change to followers via a replication log; followers apply in the same order. (3) Reads go to leader or any follower — but writes only to the leader.' },
    { id: 'semi-sync', lesson: 'Ch 5', front: 'Semi-synchronous replication — what does it guarantee?', back: 'One follower is synchronous, the rest async (promoted if the sync one fails). Guarantee: an up-to-date copy exists on at least two nodes — the leader plus one sync follower.' },
    { id: 'failover-fraught', lesson: 'Ch 5', front: 'Automatic failover’s three stages — and why is it “fraught”?', back: 'Detect failure by timeout (~30 s), elect the most up-to-date follower, reconfigure clients. Fraught: async replication means discarded writes, split brain, and the timeout dilemma — too short causes unnecessary failovers that make a struggling system worse.' },
    { id: 'split-brain-fencing', lesson: 'Ch 5', front: 'Split brain — and the safety catch?', back: 'Two nodes both believe they are the leader and both accept writes — data loss or corruption without conflict resolution. The catch is fencing (STONITH — Shoot The Other Node In The Head); badly designed, it can shut down BOTH nodes.' },
    { id: 'github-pk-collision', lesson: 'Ch 5', front: 'The GitHub/MySQL incident — what happened?', back: 'An out-of-date MySQL follower was promoted; its autoincrement counter lagged, so it reused primary keys the old leader had assigned. The keys were shared with Redis, and the MySQL/Redis inconsistency disclosed private data to the wrong users.' },
    { id: 'wal-shipping', lesson: 'Ch 5', front: 'WAL shipping — the advantage and the coupling cost?', back: 'Replicate the storage engine’s own write-ahead log — followers build byte-identical data. But the log describes which bytes changed in which disk blocks, so replication is tied to one storage-engine version: no zero-downtime rolling upgrades.' },
    { id: 'logical-log-cdc', lesson: 'Ch 5', front: 'Logical (row-based) replication log — what’s in it, and why is it useful?', back: 'Row-granularity records: inserts carry new column values, deletes carry the primary key (or old values), updates carry the key plus new values. Decoupled from the storage engine → version compatibility and change data capture for warehouses, indexes, caches.' },
    { id: 'monotonic-reads', lesson: 'Ch 5', front: 'Monotonic reads — the anomaly and the fix', back: 'Reading from different replicas can show time going backward — a comment appears, then disappears on refresh. Fix: pin each user to one replica (e.g., hash of user ID); reroute only if that replica fails.' },
    { id: 'consistent-prefix-reads', lesson: 'Ch 5', front: 'Consistent prefix reads — Mrs. Cake says what?', back: 'When replication lags unevenly, an observer can see the answer before the question. The guarantee: writes that happen in an order are seen in that order. Fix: keep causally related writes on the same partition, or track causal dependencies.' },
    { id: 'multi-leader-when', lesson: 'Ch 5', front: 'The three use cases where multi-leader replication makes sense', back: '(1) Multi-datacenter — writes stay local, async cross-DC replication. (2) Offline clients — every device is a tiny “datacenter” (calendar sync; CouchDB). (3) Collaborative editing — per-keystroke changes without locking. Within one datacenter it rarely pays.' },
    { id: 'lww-dangers', lesson: 'Ch 5', front: 'Last write wins — why is it dangerous, and how do you use it safely?', back: 'Concurrent writes get an arbitrary timestamp order, so even writes acknowledged as successful (each reached w replicas) are silently discarded — all but one. Safe only with immutable keys written once — e.g., a UUID per write.' },
    { id: 'crdt', lesson: 'Ch 5', front: 'CRDT — what is it good for?', back: 'A conflict-free replicated datatype — sets, maps, counters, ordered lists that automatically merge concurrent edits in sensible ways (Riak 2.0). Removes the need for users to hand-merge siblings. Related: three-way merge structures (Git-like) and operational transformation (Google Docs).' },
    { id: 'hinted-handoff', lesson: 'Ch 5', front: 'Sloppy quorums and hinted handoff — the couch analogy', back: 'Locked out of your house (network cut off from a value’s home nodes)? Sleep on the neighbor’s couch (accept w responses from non-home nodes). When you find your keys (network heals), the neighbor sends you home (writes forwarded to home nodes — hinted handoff). Buys write availability; loses the freshness guarantee until handoff completes.' },
    { id: 'read-repair-anti-entropy', lesson: 'Ch 5', front: 'Read repair vs. anti-entropy — the two catch-up mechanisms', back: 'Read repair: a client reading several replicas writes the newer value back to a stale one — works for frequently-read values. Anti-entropy: a background process scans for differences and copies missing data — unordered and possibly slow. Without anti-entropy (Voldemort), rarely-read values can just be missing.' },
    { id: 'happens-before', lesson: 'Ch 5', front: 'How does the book define “concurrent” operations?', back: 'A happens before B if B knows about, depends on, or builds upon A. Two operations are concurrent if neither happens before the other — physical timing is irrelevant (it’s about knowledge, hence the relativity comparison).' },
    { id: 'version-vector', lesson: 'Ch 5', front: 'Version vectors — what do they buy over timestamps?', back: 'One version number per replica per key (each replica tracks the versions it has seen from the others) — the database can distinguish overwrites from concurrent writes without trusting clocks. Clients return them on write (Riak’s “causal context”); safe to read one replica and write another.' },

    /* ---------- Chapter 6: Partitioning ---------- */
    { id: 'consistent-hashing', lesson: 'Ch 6', front: 'Consistent hashing — and why does the book say to avoid the term?', back: 'Karger et al.: randomly chosen partition boundaries avoiding central control — “consistent” refers to rebalancing, not replica/ACID consistency. It doesn’t actually work well for databases, so docs using the term are often inaccurate. Say “hash partitioning” instead.' },
    { id: 'partition-terminology', lesson: 'Ch 6', front: 'What do other systems call a “partition”?', back: 'Shard (MongoDB, Elasticsearch, SolrCloud), region (HBase), tablet (Bigtable), vnode (Cassandra, Riak), vBucket (Couchbase). Each record belongs to exactly one partition; each partition is a small database of its own.' },
    { id: 'key-range-partitioning', lesson: 'Ch 6', front: 'Key-range partitioning — the advantage and the risk?', back: 'A partition owns a continuous key range; keys sorted within it → efficient range scans and concatenated-index tricks. Risk: clustered access patterns (timestamps, IDs) concentrate onto adjacent ranges — hot spots.' },
    { id: 'hash-partitioning', lesson: 'Ch 6', front: 'Hash partitioning — what it buys and what it costs?', back: 'A partition owns a range of hashes → even load even for skewed keys (Cassandra/MongoDB use MD5, Voldemort uses Fowler–Noll–Vo). But key ordering is destroyed: range queries fan out to all partitions (MongoDB hash mode) or aren’t supported (Riak, Couchbase, Voldemort).' },
    { id: 'skew-hotspot', lesson: 'Ch 6', front: 'Skew vs. hot spot — definitions?', back: 'Skew: unfair partitioning — some partitions have more data or queries. Hot spot: a disproportionately loaded partition; extreme case: all load on one partition, 9 of 10 nodes idle.' },
    { id: 'hot-key-split', lesson: 'Ch 6', front: 'The random-number trick for one hot key — and its three costs?', back: 'Prepend/append a two-digit random number to split the key’s writes across 100 keys on different partitions. Costs: reads must combine all 100; bookkeeping to track split keys; pure overhead for the vast majority of cold keys.' },
    { id: 'compound-key-cassandra', lesson: 'Ch 6', front: 'Cassandra’s compound primary key (user_id, update_timestamp) — what do you get?', back: 'Only the first column is hashed to pick the partition; the rest is a concatenated sort index within it. Efficient per-user time-range scans, users spread across partitions — but no range queries over the first column.' },
    { id: 'local-index', lesson: 'Ch 6', front: 'Local (document-partitioned) secondary index — write vs. read cost?', back: 'Each partition indexes only its own documents. Writes touch one partition. Reads scatter/gather across all partitions — prone to tail latency amplification (MongoDB, Riak, Cassandra, Elasticsearch, SolrCloud, VoltDB).' },
    { id: 'global-index', lesson: 'Ch 6', front: 'Global (term-partitioned) secondary index — read vs. write cost?', back: 'The index is partitioned by the searched term (or its hash), covering all partitions. Reads hit one partition. Writes touch every index partition holding a term from the document; updates are usually asynchronous (immediate sync needs distributed transactions).' },
    { id: 'scatter-gather', lesson: 'Ch 6', front: 'Scatter/gather — and its latency problem?', back: 'Send the query to ALL partitions and combine results — required for local secondary indexes. Even in parallel, the query is as slow as the slowest partition: tail latency amplification.' },
    { id: 'hash-mod-n', lesson: 'Ch 6', front: 'Why is hash(key) mod N a rebalancing disaster?', back: 'Change N and most keys move: 123456 mod 10 = 6, mod 11 = 3, mod 12 = 0. The whole dataset reshuffles instead of moving only what changed.' },
    { id: 'fixed-partitions', lesson: 'Ch 6', front: 'Fixed number of partitions — how does a node join?', back: 'Create many more partitions than nodes (e.g., 1,000 on 10); the new node steals a few whole partitions from each existing node. Key→partition never changes — only partition→node does. Riak, Elasticsearch, Couchbase, Voldemort.' },
    { id: 'dynamic-partitioning', lesson: 'Ch 6', front: 'Dynamic partitioning — mechanism and the empty-database caveat?', back: 'Split partitions that grow too big (HBase: 10 GB), merge small ones — like B-tree top-level splitting. Caveat: an empty DB starts with one partition, so all writes hit one node until the first split — pre-split if you know the key distribution.' },
    { id: 'partitions-per-node', lesson: 'Ch 6', front: 'Partitioning proportionally to nodes (Cassandra)?', back: 'A fixed number of partitions per node (Cassandra default: 256). A new node randomly picks partitions to split and takes half of each. Partition size stays fairly stable as the dataset and cluster grow together.' },
    { id: 'routing-tier', lesson: 'Ch 6', front: 'The three ways to route a request to the right node?', back: '(1) Client contacts any node (round-robin), which forwards if it doesn’t own the partition; (2) routing tier — a partition-aware load balancer that handles no requests itself; (3) partition-aware clients connect directly.' },
    { id: 'zookeeper-gossip', lesson: 'Ch 6', front: 'ZooKeeper routing vs. gossip routing?', back: 'ZooKeeper: an external coordination service holds the authoritative partition→node map; nodes register, routing tiers subscribe (HBase, SolrCloud, Kafka; MongoDB uses config servers + mongos). Gossip (Cassandra, Riak): nodes disseminate state among themselves; any node forwards — no external dependency.' },
    { id: 'mpp', lesson: 'Ch 6', front: 'MPP — massively parallel processing?', back: 'Analytic relational databases where the optimizer breaks a query (joins, filters, grouping, aggregation) into execution stages and partitions that run in parallel across nodes — big scans benefit most.' },

    /* ---------- Chapter 7: Transactions ---------- */
    { id: 'write-skew', lesson: 'Ch 7', front: 'Write skew — define it via the doctors example', back: 'Two transactions read the same data, make disjoint writes, and break an invariant (“at least one doctor on-call”). Both commit legally — only serializable prevents it.' },
    { id: 'snapshot-isolation', lesson: 'Ch 7', front: 'Snapshot isolation / MVCC — what do you get?', back: 'Each transaction reads a consistent point-in-time snapshot; readers never block writers. Prevents dirty and non-repeatable reads — but not write skew.' },
    { id: 'ssi', lesson: 'Ch 7', front: 'Why is SSI (serializable snapshot isolation) optimistic?', back: 'No locks. Track each txn’s read set; if another txn’s write invalidates it before commit, abort and retry. Detect dangerous read→write dependencies instead of blocking.' },
    { id: 'acid-atomicity', lesson: 'Ch 7', front: 'ACID atomicity — what it means and what it does NOT mean', back: 'NOT about concurrency (that’s isolation): it means a fault partway through a multi-write transaction aborts it and discards all its writes — so it can be safely retried. Really “abortability.”' },
    { id: 'acid-consistency', lesson: 'Ch 7', front: 'Why doesn’t the C belong in ACID?', back: 'ACID consistency is the application’s own invariants (“credits and debits balance”) — the database can’t stop you from writing bad data. A, I, and D are database properties; C is an application property (Hellerstein: “tossed in to make the acronym work”).' },
    { id: 'durability-illusion', lesson: 'Ch 7', front: '“Perfect durability does not exist” — why the skepticism?', back: 'SSDs violate fsync guarantees on power loss; correlated faults (power outage, a bug) can kill all replicas; async replication loses recent writes; corruption can spread to backups. Use disk + remote replication + backups together — they’re risk reductions, not guarantees.' },
    { id: 'single-object-vs-transactions', lesson: 'Ch 7', front: 'Are compare-and-set and atomic increments “transactions”?', back: 'No — marketing calls them “lightweight transactions,” but a transaction is a mechanism for grouping multiple operations on multiple objects. Single-object atomicity/isolation is nearly universal, but multi-object coordination is the real thing.' },
    { id: 'retry-limits', lesson: 'Ch 7', front: 'Five reasons retrying an aborted transaction isn’t always safe', back: '(1) It may have actually committed — the ack was lost — so the retry performs it twice. (2) If the error is overload, retries make it worse. (3) Only transient errors (deadlock, failover) are worth retrying; constraint violations aren’t. (4) Side effects outside the DB (emails) don’t roll back. (5) The retrying client can die and lose the data.' },
    { id: 'dirty-read', lesson: 'Ch 7', front: 'Dirty read — definition and why it matters', back: 'Reading another transaction’s writes before it commits. You might see a partially-updated multi-object state, or data that later gets rolled back — never truly existed. Prevented by read committed.' },
    { id: 'dirty-write', lesson: 'Ch 7', front: 'Dirty write — the used-car example', back: 'Overwriting a value another transaction wrote but hasn’t committed. Alice and Bob buy the same car: the listing ends up Bob’s, the invoice Alice’s. Prevented by read committed (the second write waits).' },
    { id: 'read-committed-impl', lesson: 'Ch 7', front: 'How is read committed implemented?', back: 'Dirty writes: row-level locks held to commit/abort. Dirty reads: version tracking — the database keeps the old committed value alongside the new one and serves reads the old value until the write commits. Read locks would make one long write block all readers.' },
    { id: 'mvcc-visibility', lesson: 'Ch 7', front: 'MVCC visibility — why does txn 12 still see the $500?', back: 'Rows carry created_by/deleted_by (txid); updates are delete + create. Visibility: ignore writes from in-progress, aborted, or later transactions; see everything else. Txn 12 ignores txn 13’s uncommitted deletion and creation, so the old version is what it reads.' },
    { id: 'repeatable-read-naming', lesson: 'Ch 7', front: '“Nobody knows what repeatable read means” — why?', back: 'The SQL standard predates snapshot isolation and defines a superficially similar level — ambiguously. PostgreSQL/MySQL call SI “repeatable read”; Oracle calls SI “serializable”; DB2 uses “repeatable read” for actual serializability. Same name, wildly different guarantees.' },
    { id: 'lost-update-fixes', lesson: 'Ch 7', front: 'Four defenses against lost updates', back: '(1) Atomic write operations (value = value + 1). (2) Explicit locking — SELECT FOR UPDATE. (3) Automatic detection (PostgreSQL RR, Oracle “serializable”, SQL Server SI — but not MySQL InnoDB). (4) Compare-and-set — only if its WHERE clause doesn’t read a stale snapshot. In replicated DBs: merge siblings or use commutative operations.' },
    { id: 'phantom', lesson: 'Ch 7', front: 'Phantom — define it', back: 'A write in one transaction changes the result of another transaction’s search query — typically an inserted row matching a condition the other transaction found empty. If the check returns no rows, SELECT FOR UPDATE has nothing to lock — hence predicate locks, index-range locks, or materializing conflicts.' },
    { id: 'materializing-conflicts', lesson: 'Ch 7', front: 'Materializing conflicts — how and why is it a last resort?', back: 'Pre-create concrete lock objects — e.g., a table of room × 15-minute time slots for the next six months — and SELECT FOR UPDATE on them before checking and inserting. Converts a phantom into a row lock. Ugly: concurrency control leaks into the data model.' },
    { id: 'serial-execution', lesson: 'Ch 7', front: 'Actual serial execution — what made it feasible (~2007), and its limits?', back: 'Cheap RAM (active dataset in memory) + short OLTP transactions as deterministic stored procedures (no network round trips). VoltDB, Redis, Datomic. Limits: one slow transaction stalls everything; dataset must fit memory; write throughput capped at one core — partition, but cross-partition txns run at ~1,000 writes/sec.' },
    { id: '2pl-rules', lesson: 'Ch 7', front: '2PL in one card — locks, deadlock handling, and the mantra it breaks', back: 'Shared locks for readers, exclusive for writers, held to end of transaction (two phases: acquire, then release). Writers block readers and vice versa — breaking snapshot isolation’s “never block” mantra — which is what makes it serializable. Deadlocks are detected and one transaction is aborted for retry. 2PL ≠ 2PC!' },
    { id: 'predicate-lock', lesson: 'Ch 7', front: 'Predicate locks vs. index-range locks', back: 'Predicate lock: covers all objects matching a search condition — even ones that don’t exist yet (phantoms). Too slow to check, so databases approximate with index-range locks (next-key locking) attached to index entries — locking a superset is safe; fallback is a whole-table lock.' },

    /* ---------- Chapter 8: The Trouble with Distributed Systems ---------- */
    { id: 'partial-failure', lesson: 'Ch 8', front: 'Partial failure — define it, and why it hurts', back: 'Some parts of the system broken unpredictably while others work fine. Nondeterministic: the same multi-node operation may work, fail, or leave you unsure whether it succeeded at all. The defining characteristic of distributed systems.' },
    { id: 'network-partition', lesson: 'Ch 8', front: 'Network partition (netsplit)?', back: 'One part of the network cut off from the rest by a network fault. The book says “network fault” instead, to avoid confusion with partitions (shards) of a storage system.' },
    { id: 'timeout-guess', lesson: 'Ch 8', front: 'Why is a timeout “a guess,” and what goes wrong when it’s too short?', back: 'Asynchronous networks have unbounded delays and servers can’t promise max processing time — there’s no correct timeout value, only experimental ones. Too short: you declare merely-slow nodes dead, transfer their load, and can trigger a cascading failure — or perform an action twice (email sent by both old and new leader).' },
    { id: 'queueing-delay', lesson: 'Ch 8', front: 'The four places a packet queues', back: '(1) The network switch — several senders to one destination; full queue = dropped packet. (2) The destination OS — all CPU cores busy. (3) The VM monitor — paused tens of ms while another VM runs. (4) The TCP sender itself — flow control / backpressure before the data even enters the network.' },
    { id: 'circuit-vs-packet', lesson: 'Ch 8', front: 'Circuit switching vs. packet switching in one card', back: 'Circuits (telephone, ISDN: 16 bits every 250 µs, guaranteed) reserve bandwidth at every hop — no queueing, bounded delay, but wasteful for bursty traffic and idle connections. Packets (Ethernet/IP) jostle for whatever bandwidth exists — maximum utilization, but queueing and unbounded delays.' },
    { id: 'tod-vs-monotonic', lesson: 'Ch 8', front: 'Time-of-day vs. monotonic clock — which is for what?', back: 'Time-of-day (CLOCK_REALTIME / System.currentTimeMillis): calendar time since the epoch, NTP-synced, may jump backward — for points in time (“when was this published?”). Monotonic (CLOCK_MONOTONIC / System.nanoTime): always moves forward, meaningless absolute value, not comparable across machines — for durations (timeouts).' },
    { id: 'ntp-slew', lesson: 'Ch 8', front: 'NTP stepping vs. slewing — and the drift numbers', back: 'Slewing: NTP adjusts the clock’s rate up to ±0.05% (monotonic clock too). Stepping/forced reset: if the clock is too far off, it jumps — and apps see time go backward. Google assumes 200 ppm drift: up to 6 ms between 30-second resyncs, or 17 seconds if you resync only daily.' },
    { id: 'leap-second-smearing', lesson: 'Ch 8', front: 'Leap seconds — the problem and the kind fix', back: 'A minute that is 59 or 61 seconds long, which has crashed many large systems (Cloudflare’s DNS, 2017). Smearing: NTP servers “lie,” performing the adjustment gradually over the course of a day instead of one jarring jump.' },
    { id: 'lww-data-loss', lesson: 'Ch 8', front: 'Why does last-write-wins lose data? (Figure 8-3)', back: 'LWW compares time-of-day timestamps from different nodes. With <3 ms of skew, a causally-later write (x=2, ts 42.003) can carry an earlier timestamp than x=1 (42.004) — so node 2 keeps x=1 and silently drops the increment. A lagging node can’t overwrite a fast node until the skew has elapsed; NTP can’t fix it (limited by network RTT). Logical clocks are the safer ordering tool.' },
    { id: 'uncertainty-bound', lesson: 'Ch 8', front: 'A clock reading is not a point — what is it?', back: 'A confidence interval: the system may be 95% sure the time is between 10.3 and 10.5 s, but no finer. If you know the time ±100 ms, the microsecond digits are meaningless — and clock_gettime() never tells you whether its error is 5 ms or 5 years.' },
    { id: 'truetime', lesson: 'Ch 8', front: 'TrueTime + Spanner’s commit wait', back: 'TrueTime returns [earliest, latest] instead of a point. If two transactions’ intervals don’t overlap, their order is certain — so Spanner deliberately waits out the confidence interval before committing. GPS receivers or atomic clocks in every datacenter keep the interval to ~7 ms.' },
    { id: 'process-pauses', lesson: 'Ch 8', front: 'Six reasons a thread can pause (Ch 8)', back: '(1) Stop-the-world GC — up to minutes, even “concurrent” collectors. (2) VM suspension / live migration. (3) Laptop lid close. (4) OS context switch / hypervisor steal time. (5) Synchronous disk I/O (lazy classloading, network EBS). (6) Swapping / thrashing. Plus SIGSTOP. None of them notify the thread.' },
    { id: 'lease-gc-hazard', lesson: 'Ch 8', front: 'Why do leases break under GC pauses?', back: 'The leader renews a lease if <10 s remain, then processes requests — but a 15-second pause between the check and the processing outlives the lease. On resume, nothing tells the thread time passed; it acts as leader while another node has taken over. Two leaders, one file: corruption. (Also: the expiry is set by another machine’s clock, so it needs synchronized clocks too.)' },
    { id: 'fencing-token', lesson: 'Ch 8', front: 'Fencing tokens — how they stop the zombie leader', back: 'The lock server returns a monotonically increasing token with every grant (client 1: 33, client 2: 34). Writes must carry the token, and the storage server rejects any token older than the highest processed — so client 1’s post-pause write with token 33 is refused. The server must check; a client can’t be trusted to know its own state. ZooKeeper: zxid or cversion works as the token.' },
    { id: 'byzantine-fault', lesson: 'Ch 8', front: 'Byzantine fault vs. crash fault', back: 'Crash: unreliable but honest — if it responds, it plays by the rules. Byzantine: the node “lies,” sending arbitrary faulty or corrupted responses. BFT needs a supermajority (>2/3) of correct nodes; worth it for aerospace (radiation flips bits) and multi-org systems (blockchains), not for single-company datacenters. A software bug on identical nodes can’t be BFT’d away.' },
    { id: 'two-generals', lesson: 'Ch 8', front: 'The Two Generals Problem — and its Byzantine generalization', back: 'Two generals must agree on a battle plan via messengers who may be delayed or lost — like packets in a network. The Byzantine version: n generals, some secretly traitors sending fake messages, and no one knows who. Named for “Byzantine” = devious, not for actual Byzantine intrigue (Lamport was talked out of “The Albanian Generals Problem”).' },
    { id: 'quorum-truth', lesson: 'Ch 8', front: '“The truth is defined by the majority” — what does that mean?', back: 'A node can’t trust its own judgment (it may be semi-disconnected or freshly un-paused). Decisions — including “is this node dead?” — require a quorum, and a node declared dead by a majority must step down even if it feels alive. A majority is safe (there can be only one) and tolerant: 3 nodes survive 1 failure, 5 survive 2.' },
    { id: 'safety-liveness', lesson: 'Ch 8', front: 'Safety vs. liveness — the two kinds of correctness properties', back: 'Safety: “nothing bad happens”; violations can be pinned to a moment and can never be undone — must hold even if every node crashes. Liveness: “something good eventually happens”; may not hold now, but there’s always hope — caveats allowed (majority alive, network eventually recovers). Eventual consistency is a liveness property.' },
    { id: 'system-model', lesson: 'Ch 8', front: 'System models — the timing × failure grid', back: 'Timing: synchronous (bounded delays — unrealistic), partially synchronous (bounded most of the time — realistic), asynchronous (no clock at all). Failures: crash-stop (dead forever), crash-recovery (may return; disk survives, memory lost), Byzantine (anything). Most useful for real systems: partially synchronous + crash-recovery.' },

    /* ---------- Chapter 9: Consistency and Consensus ---------- */
    { id: 'cap', lesson: 'Ch 9', front: 'CAP theorem in one line', back: 'During a network partition you must choose: give up linearizable consistency (stay available) or give up availability (stay consistent). You can’t have both while the partition lasts.' },
    { id: 'linearizability', lesson: 'Ch 9', front: 'Linearizability — what guarantee?', back: 'Operations on a register behave as if there were a single copy with a real-time total order — the system appears to be one machine, even though it’s replicated.' },
    { id: 'causal-consistency', lesson: 'Ch 9', front: 'Causal consistency vs. linearizability', back: 'Causal orders only causally-related events (weaker), but it’s achievable during network partitions — the useful weaker guarantee when linearizability costs you availability (CAP).' },
    { id: '2pc-blocking', lesson: 'Ch 9', front: 'Why does 2PC block?', back: 'After voting yes, a participant can neither commit nor abort alone. If the coordinator dies between prepare and commit, everyone is stuck until it recovers.' },
    { id: 'raft', lesson: 'Ch 9', front: 'Raft/Paxos consensus — key mechanics', back: 'A leader establishes a total order (total order broadcast) with epoch/term numbering; quorum voting. With 2f+1 nodes, the system tolerates f failures.' },
    { id: 'lin-vs-ser', lesson: 'Ch 9', front: 'Linearizability vs serializability — the one-line distinction', back: 'Serializability: an isolation property of transactions (multi-object, “some serial order”). Linearizability: a recency guarantee on reads/writes of a single register. Both together = strict serializability (strong-1SR). SSI is serializable but NOT linearizable — snapshots exclude recent writes by design.' },
    { id: 'cap-nuance', lesson: 'Ch 9', front: 'CAP — why “pick 2 of 3” is the wrong reading', back: 'A partition is a fault, not a feature — it happens whether you like it or not. Healthy network: both consistency and availability. Partitioned: choose. Honest phrasing: “Consistent or Available when Partitioned.” The formal theorem covers only linearizability and node disconnection — nothing about delays or dead nodes.' },
    { id: 'cap-cost-speed', lesson: 'Ch 9', front: 'If CAP isn’t the usual reason, why do so few systems go linearizable?', back: 'Performance. Even multi-core RAM isn’t linearizable (per-core caches, store buffers — you need memory barriers). Attiya–Welch: linearizable response time is at least proportional to network delay uncertainty — so linearizability is slow all the time, not just during faults.' },
    { id: 'causal-strongest-available', lesson: 'Ch 9', front: 'Why is causal consistency the sweet spot?', back: 'Linearizability implies causality but costs coordination; causal consistency is the STRONGEST model that doesn’t slow down with network delays and stays available under partitions (CAP doesn’t apply to it). Linearizability = total order; causality = partial order (Git-like branching and merging).' },
    { id: 'seqnum-broken-generators', lesson: 'Ch 9', front: 'Three popular sequence-number generators — and the shared flaw', back: '(1) Odd/even per node, (2) wall-clock timestamps, (3) preallocated blocks (A: 1–1,000, B: 1,001–2,000). All faster than one leader counter — and all can assign a causally-later operation a LOWER number (rates differ, clocks skew, blocks invert).' },
    { id: 'lamport-max', lesson: 'Ch 9', front: 'Lamport timestamps — the one rule that makes them causality-safe', back: 'A timestamp is (counter, node ID). Every node AND client tracks the maximum counter it has ever seen and includes it in every request; a node seeing a higher max immediately jumps its counter to it. Each causal dependency therefore produces a strictly greater timestamp.' },
    { id: 'lamport-vs-vectors', lesson: 'Ch 9', front: 'Lamport timestamps vs version vectors', back: 'Version vectors distinguish concurrent from causally-dependent operations; Lamport timestamps always total-order, so you can’t tell which case you’re in. Lamport’s compensation: more compact. Also: a total order only exists once you’ve collected all the operations — useless for deciding username uniqueness right now.' },
    { id: 'tob-logging', lesson: 'Ch 9', front: 'Total order broadcast — the two properties, and the log view', back: 'Reliable delivery (no losses) + totally ordered delivery (same order everywhere), with the order FIXED at delivery time — no retroactive inserts. Delivering a message = appending to a log everyone reads identically. Powers state machine replication, serializable transactions, fencing tokens (zxid). Equivalent to consensus.' },
    { id: 'atomic-commit-irrevocable', lesson: 'Ch 9', front: 'Why can’t a committed transaction be un-committed later?', back: 'Once committed, data is visible to other transactions that may already rely on it — un-committing would force reverting them too (the read-committed foundation). On one node, the disk controller makes the commit atomic: data written first, commit record second; the instant the commit record lands, it’s decided.' },
    { id: '2pc-promises', lesson: 'Ch 9', front: '2PC’s two points of no return', back: '(1) Voting “yes” to prepare — the participant has durably written its data and surrendered the right to abort unilaterally. (2) The coordinator’s commit point — writing commit/abort to its transaction log on disk. After that the decision is enforced with infinite retries; even a crashed participant commits on recovery.' },
    { id: 'xa-in-doubt', lesson: 'Ch 9', front: 'Coordinator dies between prepare and commit — what happens?', back: 'In-doubt participants can neither abort (another may have committed) nor commit (another may have aborted) — even a timeout doesn’t help. They hold row locks the whole time (a 20-minute restart = 20 minutes of blocked rows; reboots preserve the locks by design). XA escape hatch: “heuristic decisions” — a euphemism for probably breaking atomicity.' },
    { id: 'epoch-quorum', lesson: 'Ch 9', front: 'Epochs + quorums — how leader changes stay safe', back: 'Epoch/ballot/term numbers are monotonic; the leader is unique per epoch and the higher epoch wins conflicts. Two rounds of voting — elect the leader, then vote on its proposals — with OVERLAPPING quorums, so at least one node in every successful proposal vote also participated in the latest election. Unlike 2PC: the leader is elected, and only a majority (not all) must say yes.' },
    { id: 'consensus-properties', lesson: 'Ch 9', front: 'The four consensus properties — and which one 2PC fails', back: 'Uniform agreement (no two nodes decide differently), integrity (no node decides twice), validity (a decided value was proposed) — all safety. Termination (every non-crashed node eventually decides) — liveness, needs a majority: 2f+1 nodes tolerate f failures. 2PC satisfies the safety three but fails termination: it waits for the coordinator.' },
    { id: 'leader-election-circularity', lesson: 'Ch 9', front: '“To elect a leader we must first elect a leader” — resolve it', back: 'A human-configured leader is a dictatorship: agreement/integrity/validity hold, termination doesn’t. Automatic failover needs consensus to avoid split brain — and consensus ≈ total order broadcast ≈ single-leader replication. The escape: consensus protocols only guarantee ONE leader per epoch, not globally — higher epoch wins, stale leaders are fenced by quorum votes.' },
    { id: 'zk-features', lesson: 'Ch 9', front: 'ZooKeeper/etcd — what they actually provide', back: 'Small in-memory datasets replicated via total order broadcast (Zab/Raft): linearizable CAS (locks as leases), total operation ordering (zxid → fencing tokens), failure detection via heartbeat sessions, and change notifications (watches). Only the CAS needs consensus — the combination is what makes it the coordination toolkit. Runs on 3–5 nodes serving thousands of clients; HBase, YARN, OpenStack Nova, and Kafka have all depended on it.' },
    { id: 'zk-session-expiry', lesson: 'Ch 9', front: 'ZooKeeper session expiry — the trap', back: 'A GC-paused client’s heartbeats stop; after the session timeout it is declared dead and its ephemeral nodes (locks!) vanish. On waking, the client still believes it holds the lock — nothing told the thread about the pause. Defense: fencing tokens — ZooKeeper’s zxid or cversion, checked server-side by the resource.' },

    /* ---------- Chapter 10: Batch Processing ---------- */
    { id: 'batch-processing-def', lesson: 'Ch 10', front: 'Online vs batch vs stream — the three system types', back: 'Online (services): wait for requests, respond fast; measured by response time, availability is critical. Batch (offline): large fixed input, minutes-to-days, nobody waiting, scheduled periodically; measured by throughput. Stream (nearline/near-real-time): consume and produce events shortly after they happen — between the two.' },
    { id: 'unix-pipe-wiring', lesson: 'Ch 10', front: 'stdin/stdout — why Unix separates logic from wiring', back: 'A program that just reads stdin and writes stdout doesn’t know or care where input comes from or output goes — the SHELL decides (keyboard/screen, files, or a pipe to another process). Loose coupling / late binding / inversion of control: what makes composing small tools into big systems possible.' },
    { id: 'uniform-interface-card', lesson: 'Ch 10', front: 'Uniform interface — definition and why it’s rare', back: 'All programs share the same I/O interface, so any output feeds any input. In Unix: the file (an ordered byte sequence) — a disk file, a pipe, a device driver, a TCP connection all look alike. Rare and precious: URLs/HTTP are another example; databases can’t easily exchange data, which Balkanizes it.' },
    { id: 'mapreduce-def', lesson: 'Ch 10', front: 'MapReduce — the four-step pattern', back: '(1) Break input files into records, (2) call the mapper per record → emit key-value pairs, (3) the FRAMEWORK sorts all pairs by key (always, implicitly), (4) call the reducer once per key over its values. Mapper = put data into a form suitable for sorting; reducer = process what sorting grouped. A job = a Unix process, industrialized.' },
    { id: 'mapper-reducer-purity', lesson: 'Ch 10', front: 'What may mappers and reducers assume?', back: 'Nothing about neighbors: one record (or key-group) at a time, stateless, no side effects beyond output, no knowledge of where input came from. That restriction is what lets the framework retry tasks safely and move data between machines — your code never sees the parallelism or the failures.' },
    { id: 'shuffle-card', lesson: 'Ch 10', front: 'The MapReduce shuffle — what it is, and what it isn’t', back: 'Each mapper partitions its output by reducer (hash of key) into sorted files on LOCAL disk; reducers fetch their partition from every mapper over the network and merge, preserving sort order. No randomness — unlike a deck of cards. #map tasks = input blocks; #reduce tasks = configured by you.' },
    { id: 'hdfs-card', lesson: 'Ch 10', front: 'HDFS — architecture and scale', back: 'Shared-nothing GFS reimplementation: a daemon per machine exposing its disks over the network, plus a central NameNode tracking which blocks live where. Fault tolerance by replication or erasure coding (Reed–Solomon). Biggest deployments: tens of thousands of machines, hundreds of petabytes — commodity hardware, no special interconnects.' },
    { id: 'speculative-execution', lesson: 'Ch 10', front: 'Speculative execution — what and why', back: 'The framework runs backup copies of straggler tasks and takes whichever finishes first. One more reason mappers/reducers must be side-effect-free: several attempts of one task may run, but only one’s output becomes visible.' },
    { id: 'reduce-side-join-card', lesson: 'Ch 10', front: 'Reduce-side (sort-merge) join — mechanism and secondary sort', back: 'Mappers on BOTH inputs emit (join key, record); partition-sort-merge delivers all same-key records to one reducer call — e.g., the user profile plus all that user’s events. Secondary sort arranges within-key order (profile first, then events in timestamp order). No assumptions about inputs; pays a full shuffle of both sides.' },
    { id: 'map-side-join-card', lesson: 'Ch 10', front: 'Map-side joins — the three flavors and their assumptions', back: 'Broadcast hash: one input fits in every mapper’s memory → in-memory hash table, stream the large side, zero shuffle (Hive MapJoin, Pig replicated join). Partitioned hash: inputs partitioned identically (same key, hash, count) → join per partition (bucketed). Merge: partitioned AND sorted the same way → mappers merge directly, size irrelevant.' },
    { id: 'hot-key-card', lesson: 'Ch 10', front: 'Hot keys / linchpin objects — the problem and four fixes', back: 'A celebrity key floods one reducer while others idle — and the job (and all downstream jobs) waits for the slowest task. Fixes: Pig’s skewed join (sampling → random reducer choice, replicate the other input), Crunch’s sharded join (declare hot keys), Hive’s skewed join (separate files, join map-side), and two-stage aggregation (partial aggregates at random reducers, then combine).' },
    { id: 'batch-outputs', lesson: 'Ch 10', front: 'Why batch outputs are files, not database writes', back: 'Writing to a DB from inside a job: per-record network requests are slow, parallel tasks swamp the DB, and partial side effects break the all-or-nothing guarantee. Instead: build a new database in the output directory — search indexes (5–10 job workflows) or read-only KV stores (Voldemort, ElephantDB, HBase bulk load), bulk-loaded with an atomic switchover. Bonus: human fault tolerance — buggy output can simply be regenerated.' },
    { id: 'google-preemption', lesson: 'Ch 10', front: 'Google’s preemption numbers — and what they explain', back: 'Mixed-use datacenters: batch tasks run at low priority and are preempted for higher-priority work — a 1-hour task has ~5% termination risk (an order of magnitude above hardware failures), so 100 ten-minute tasks face >50% that one is killed. MapReduce’s task-level retry exists for preemption, not flaky hardware.' },
    { id: 'materialization', lesson: 'Ch 10', front: 'Materialization of intermediate state — the three costs', back: 'MapReduce jobs only connect via HDFS directories: (1) a job waits for ALL of its predecessor’s tasks (stragglers block the workflow), (2) downstream mappers often just re-read what the last reducer wrote, (3) replicated HDFS files are overkill for scratch data. Unix pipes materialize nothing — they stream through a small buffer.' },
    { id: 'dataflow-engines-card', lesson: 'Ch 10', front: 'Spark/Tez/Flink — how they beat chained MapReduce jobs', back: 'The whole workflow is ONE job of flexibly connected operators: sort only where needed, no redundant map tasks, whole-graph locality scheduling (shared-memory buffers), intermediates in memory/local disk (not replicated HDFS), operators start as input becomes ready (Flink pipelines hardest), JVMs are reused. Fault tolerance flips from “reread durable input” to “recompute from ancestry” — Spark’s RDDs, Flink’s checkpoints — best if operators are deterministic.' },
    { id: 'dag-vs-graph', lesson: 'Ch 10', front: 'Dataflow DAG ≠ graph processing — the naming trap', back: 'Dataflow engines: the flow of data between OPERATORS is a DAG; the data itself is relational-style tuples. Graph processing: the DATA is a graph. MapReduce can’t do “repeat until done” (one pass), so graph algorithms need an external iteration loop — or Pregel, which keeps vertex state in memory across supersteps.' },
    { id: 'pregel-superstep', lesson: 'Ch 10', front: 'Pregel / BSP — the superstep model', back: 'Each superstep, every vertex processes the messages delivered from the previous one, updates its in-memory state (persists across supersteps), and sends messages delivered exactly once in the NEXT superstep — a barrier separates rounds. Vertices are like actors, but with fault tolerance (checkpointing; rollback on failure) and fixed-round delivery. If the graph fits on one machine, single-machine algorithms usually win.' },

    /* ---------- Chapter 11: Stream Processing ---------- */
    { id: 'cdc', lesson: 'Ch 11', front: 'CDC — change data capture, in one breath', back: 'Observe all data changes written to a database and extract them in a form that can be replicated to other systems — making one database the leader and the derived systems (indexes, caches, warehouses) its followers. Usually asynchronous, so replication lag applies.' },
    { id: 'event-sourcing', lesson: 'Ch 11', front: 'Event sourcing — vs. CDC', back: 'The log of events IS the source of truth; current state is derived by replaying it. In CDC the DB is still the truth and the log is a tap on it; in event sourcing the event log is the truth and every “state” is a materialized view. CDC events carry whole record versions (compaction OK); event-sourced events are intents that don’t override (full history required).' },
    { id: 'consumer-offsets', lesson: 'Ch 11', front: 'Why is Kafka replayable when queues aren’t?', back: 'It’s a durable log — consumers hold an offset, and resetting that offset replays history. Brokers don’t delete on read. Replay = reprocessing with new code, recovery from bugs, rebuilding derived systems: the batch philosophy (repeatable transformations of immutable input) made continuous.' },
    { id: 'event-def', lesson: 'Ch 11', front: 'What is an event?', back: 'A small, self-contained, immutable object with the details of something that happened at some point in time, usually timestamped — a page view, a purchase, a temperature reading, a line in the nginx access log. Grouped into topics; produced once, consumed by many.' },
    { id: 'broker-vs-db', lesson: 'Ch 11', front: 'Message broker vs database — the four differences', back: '(1) Brokers delete on delivery; DBs keep until explicit delete. (2) Brokers assume short queues (spilling degrades); (3) topic-pattern subscriptions vs secondary indexes — both are client-side selection; (4) brokers notify on change vs point-in-time query snapshots. JMS/AMQP tradition: RabbitMQ, ActiveMQ, IBM MQ.' },
    { id: 'loadbalance-vs-fanout', lesson: 'Ch 11', front: 'Load balancing vs fan-out, in messaging', back: 'Load balancing: each message to ONE consumer of a group — share the work of expensive messages (AMQP: shared queue; JMS: shared subscription). Fan-out: each message to ALL consumers — several independent “tune-ins,” like several batch jobs reading one input file. Combinable: multiple consumer groups.' },
    { id: 'partitioned-log', lesson: 'Ch 11', front: 'The partitioned log (Kafka model)', back: 'Broker storage = partitions across machines (Ch 6); a topic = a group of partitions. Producers append; consumers read sequentially (like tail -f). Within a partition, monotonically increasing offsets give a total order; across partitions, no ordering. Load balancing assigns whole partitions to consumer-group nodes; fan-out is free because reading doesn’t delete.' },
    { id: 'log-vs-traditional', lesson: 'Ch 11', front: 'When JMS/AMQP-style beats the log — and vice versa', back: 'JMS/AMQP: messages expensive to process, want message-by-message parallelism, order unimportant (task queues — async RPC). Log: high throughput, each message fast, ordering matters, and replay/durable storage needed. Two log downsides: consumers ≤ partitions, and head-of-line blocking within a partition.' },
    { id: 'disk-space-11h', lesson: 'Ch 11', front: 'The 11-hour disk calculation — and what it proves', back: 'A 6 TB drive writing at 150 MB/s fills in ~11 hours, so the log is a ring buffer holding ≥ 11 hours (days/weeks in practice). Throughput is constant regardless of retention because every message hits disk anyway — unlike memory-first brokers that degrade when spilling. Slow consumers lag the head; alert, fix, catch up — and only that consumer is affected.' },
    { id: 'dual-writes-card', lesson: 'Ch 11', front: 'The dual-writes problem — both failure modes', back: 'App writes to each system directly. (1) Race: two clients, two systems, two interleavings — DB ends B, index ends A, permanent silent inconsistency, no error anywhere. (2) Partial failure: one write succeeds, the other doesn’t — atomic commit territory. Root cause: no single leader. Fix: funnel all writes through one ordered log (CDC from the source of truth).' },
    { id: 'cdc-triggers-vs-log', lesson: 'Ch 11', front: 'CDC via triggers vs the replication log', back: 'Triggers: you choose what gets logged, but fragile with significant overhead. Replication log: robust, captures true write order (kills the dual-writes race), app is unaware — but schema changes are a challenge. Tools: Bottled Water (Postgres WAL), Maxwell/Debezium (MySQL binlog), Mongoriver (oplog), GoldenGate (Oracle), Databus/Wormhole/Sherpa at scale.' },
    { id: 'log-compaction-cdc', lesson: 'Ch 11', front: 'Log compaction in CDC — what and why', back: 'Keep only the most recent message per key; disk depends on current DB contents, not write history (tombstones mark deletes). Rebuild a derived system by consuming the compacted topic from offset 0 — a full copy of the database without a snapshot. Event sourcing can’t compact: its events are intents that don’t override each other.' },
    { id: 'command-vs-event', lesson: 'Ch 11', front: 'Command vs event (event sourcing)', back: 'A user request starts as a command — it may still fail validation (username taken). Once validated and accepted it becomes an event: durable, immutable, a fact (“this seat WAS reserved at the time”). Consumers cannot reject events (already in the log) — so validate synchronously before publishing (or split tentative/confirm events).' },
    { id: 'immutable-ledger', lesson: 'Ch 11', front: 'State, streams, and the accountant’s ledger', back: 'State = integral of the event stream; change stream = derivative of state. Mutable state and immutable logs are two sides of one coin. Accountants knew this: append-only ledger, compensating transactions instead of erasures, corrections in the next period. Helland: “The truth is the log. The database is a cache of a subset of the log.”' },
    { id: 'cqrs-card', lesson: 'Ch 11', front: 'CQRS — what it dissolves', back: 'Command query responsibility segregation: write-optimized event log in, many read-optimized views out, derived by deterministic translation. Normalization debates become irrelevant — denormalize read views freely, since the translation keeps them consistent. Twitter’s fan-out timelines: denormalized read-optimized state, synced continuously.' },
    { id: 'eventtime-vs-proctime', lesson: 'Ch 11', front: 'Event time vs processing time — and the spike', back: 'When it happened vs when the processor saw it. Delays (queueing, restarts, reprocessing) make them diverge arbitrarily — Star Wars: episode number is event time, watch date is processing time. Window by processing time and a caught-up backlog looks like a traffic spike that never happened. Always window by event timestamps (batch jobs always knew this).' },
    { id: 'window-types-card', lesson: 'Ch 11', front: 'The four window types', back: 'Tumbling: fixed length, no overlap (round timestamps down). Hopping: fixed length, slides by a step, overlaps for smoothing (aggregate adjacent tumbles). Sliding: all events within an interval of each other, no fixed boundaries (time-sorted buffer, expire old). Session: no fixed duration — ends after an inactivity gap (e.g. 30 min); the website-analytics sessionization staple.' },
    { id: 'stream-joins-3', lesson: 'Ch 11', front: 'The three stream join types', back: 'Stream-stream: both inputs are events matched within a window (searches ⋈ clicks by session ID — you also need the un-clicked searches, so embedding is not a join). Stream-table: enrich events against a local replica kept current by the table’s changelog (window back to −∞). Table-table: two changelogs in, changes to the materialized view of the join out (Twitter timelines = tweets ⋈ follows).' },
    { id: 'cep-card', lesson: 'Ch 11', front: 'CEP — complex event processing, and the reversal', back: 'Specify rules for event PATTERNS in a stream (SQL or GUI); the engine maintains a state machine and emits a “complex event” on match. Reversal: a database stores data and treats queries as transient; CEP stores queries long-term and streams the data past them. Esper, IBM InfoSphere Streams, StreamBase; search-on-streams (Elasticsearch percolator) works the same way.' },
    { id: 'microbatch-checkpoint', lesson: 'Ch 11', front: 'Microbatching vs checkpointing — whose fault tolerance is whose?', back: 'Spark Streaming: break the stream into ~1-second miniature batches — small batches = overhead, large = latency; implicitly a processing-time tumbling window. Flink: rolling checkpoints of state to durable storage, triggered by barriers — no forced window size. Both give exactly-once WITHIN the framework — the moment output leaves it (DB writes, emails), side effects repeat.' },
    { id: 'exactly-once-card', lesson: 'Ch 11', front: 'Exactly-once semantics — the honest recipe', back: 'Output as if no faults occurred, even when they did (“effectively-once”). Inside a framework: microbatching/checkpoints/atomic commit. End to end: IDEMPOTENT writes (include the message offset to detect re-applied updates) + fencing on failover — assuming same-order replay from a log, deterministic processing, and no concurrent writers. Offsets make retries safe; they don’t make side effects vanish.' },

    /* ---------- Chapter 12: The Future ---------- */
    { id: 'unbundling', lesson: 'Ch 12', front: 'Unbundling the database — what does it mean?', back: 'An organization’s dataflow looks like one huge database: batch/stream processors are elaborate triggers and materialized-view maintenance; derived systems are index types. Unbundling = composing systems from the standalone pieces (Kafka = log, Elasticsearch = index, pipelines = view maintenance) via derived data — writes synchronized by CDC/event logs, not distributed transactions.' },
    { id: 'data-integration-card', lesson: 'Ch 12', front: 'Why data integration is unavoidable', back: 'No single tool fits all access patterns — “99% of people only need X” says more about the speaker’s experience than the technology. In complex applications, data is used in several different ways, so you inevitably cobble together several tools. Designate a system of record; derive everything else by processing its changelog in order.' },
    { id: 'lambda-arch-card', lesson: 'Ch 12', front: 'The lambda architecture — and its three problems', back: 'Immutable events feed BOTH a stream processor (fast approximate views) and a batch processor (later corrected views), merged at a serving layer. Problems: (1) two codebases to build/debug/tune (Summingbird helps, complexity remains); (2) the merge is easy only for tumbling-window aggregates — hard for joins/sessionization; (3) full reprocessing is expensive, so batches go incremental, recreating streaming complexity.' },
    { id: 'unify-batch-stream', lesson: 'Ch 12', front: 'Unifying batch and stream — the three required features', back: '(1) Replay history through the SAME engine that handles recent events (log-based brokers, HDFS input); (2) exactly-once semantics for stream processing; (3) windowing by EVENT time, not processing time (meaningless when reprocessing history). Beam API on Flink / Google Cloud Dataflow. Spark does streams on batch; Flink does batch on streams.' },
    { id: 'federated-vs-unbundled', lesson: 'Ch 12', front: 'Federated vs unbundled databases', back: 'Federated (polystore): unify READS — one query interface over many storage engines (Postgres foreign data wrappers); relational tradition, elegant semantics, complicated implementation. Unbundled: unify WRITES — CDC and event logs keeping changes flowing to all systems, idempotent consumers; Unix tradition of small tools + pipes + shell. Loose coupling: system-level fault containment, human-level independent teams.' },
    { id: 'create-index-parallel', lesson: 'Ch 12', front: 'CREATE INDEX is what, in streaming terms?', back: 'Scan a consistent snapshot, extract and sort the indexed values, write the index, process the backlog of writes since the snapshot, then keep updating — exactly setting up a new follower, or bootstrapping CDC with an initial snapshot. The database reprocesses its existing dataset and derives a new view. Reprocessing for evolution is the same move at organization scale (dual-gauge railways).' },
    { id: 'derived-state-card', lesson: 'Ch 12', front: 'Derived state — the properties that make it trustworthy', back: 'Rebuildable (deterministic functions over an immutable, replayable log — rerun to recover, verify by recomputation, time-travel debug), idempotently updatable, and clearly provenanced. Enables gradual evolution: old and new views side by side, shift a few users, increase, drop the old — every stage reversible, which lets you move faster.' },
    { id: 'separation-church-state', lesson: 'Ch 12', front: '“Separation of Church and state”', back: 'Keep stateless application logic separate from state management — the functional programming joke (Church = lambda calculus, no mutable state). Databases are poor deployment environments for app code (no package management, versioning, rolling upgrades); Mesos/YARN/Docker/K8s do that one thing well. Database = mutable shared variable you can only POLL; subscribing to changes is just emerging.' },
    { id: 'write-read-path', lesson: 'Ch 12', front: 'Write path vs read path', back: 'Write path: everything that happens EAGERLY as data arrives — through batch/stream stages until derived datasets are updated — whether or not anyone asks (eager evaluation). Read path: what happens only when someone asks (lazy evaluation). They meet at the derived dataset. The fastest, most reliable network request is no network request (the currency-conversion stream join).' },
    { id: 'views-shift-boundary', lesson: 'Ch 12', front: 'What caches, indexes, and materialized views have in common', back: 'They shift the boundary between write path and read path — precompute on writes to save work on reads. No index = grep on reads; precompute all queries = impossible (exponentially many); cache the most common queries = the useful middle. Twitter drew the boundary differently for celebrities than for ordinary users — full circle from Chapter 1.' },
    { id: 'reads-are-events', lesson: 'Ch 12', front: '“Reads are events too” — what that means', back: 'Route read requests as events through the same stream operator as writes — a stream-table join of the query stream against the database (co-partitioned like any join). One-off read = pass through the join and forget; SUBSCRIBE = a persistent join with past and future events. Also records provenance: what the user saw before deciding. Multi-partition queries (URL reach, fraud reputation) ride the same machinery.' },
    { id: 'e2e-argument-card', lesson: 'Ch 12', front: 'The end-to-end argument (Saltzer/Reed/Clark, 1984)', back: 'A function can be completely and correctly implemented only with the knowledge and help of the application at the ENDPOINTS — providing it inside the communication system is impossible (incomplete versions may still help performance). TCP dedup is per-connection; stream-processor exactly-once ends at the framework; only an end-to-end operation ID covers the user’s retry. Same for checksums and encryption.' },
    { id: 'operation-id-card', lesson: 'Ch 12', front: 'Operation identifiers — the mechanism', back: 'UUID (hidden form field) or field-hash generated at the client, passed through every hop, enforced by UNIQUE(request_id) at the database: duplicate INSERT fails → transaction aborts → charged exactly once. Holds even at weak isolation levels (app-level check-then-insert may not). Bonus: the requests table IS an event log; balances could be derived downstream.' },
    { id: 'timeliness-integrity', lesson: 'Ch 12', front: 'Timeliness vs integrity — and the slogan', back: 'Timeliness: users see up-to-date state; violations are temporary (“eventual consistency”). Integrity: no corruption — no loss, no contradictions, correct derivations; violations are permanent (“perpetual inconsistency”). Integrity matters far more: a 24-hour-lagging card statement is fine; a wrong balance is not. Dataflow systems decouple them: async = no timeliness by default, but exactly-once IS an integrity mechanism.' },
    { id: 'coordination-avoiding', lesson: 'Ch 12', front: 'Coordination-avoiding data systems — the two observations', back: '(1) Dataflow preserves integrity without atomic commit, linearizability, or synchronous coordination; (2) many applications tolerate loose constraints (apologize = compensating transaction — refunds, overbooking, overdraft fees already exist as business workflows). Combined: multi-leader across datacenters, async replication, weak timeliness, strong integrity. Aim for the apology sweet spot — coordination trades inconsistency apologies for outage apologies.' },
    { id: 'data-toxic-asset', lesson: 'Ch 12', front: 'Data as a “toxic asset”', back: 'Beyond its value, collected data carries ongoing risk: breaches, insider leaks, bankruptcy asset sales, government compulsion or theft — and future regimes. “Poor civic hygiene to install technologies that could someday facilitate a police state.” Schneier: data is the pollution problem of the information age — our grandchildren will judge us. Prescriptions: purge early, cryptographic access control, culture change.' },
    { id: 'privacy-decision-right', lesson: 'Ch 12', front: 'Privacy as a decision right', back: 'Not secrecy — the freedom to choose what to reveal to whom, where to sit on the secrecy–transparency spectrum in each situation. Surveillance doesn’t erase the right; it TRANSFERS it to the collector, who exercises it for profit and keeps the outcomes secret (revealing them would seem “creepy”). “Nothing to hide” = in line with existing power structures; consent is hollow under opacity and de facto mandatory services.' },
    { id: 'auditing-card', lesson: 'Ch 12', front: 'Trust, but verify — auditing data systems', back: 'System models are probabilities, not absolutes: bit-flips, rowhammer, disks corrupting at rest, MySQL uniqueness bugs, Postgres serializable write skew. HDFS/S3 don’t trust disks — background re-reads and replica comparison; test your backups. Event systems audit best: hash the log, rerun derivations, run redundant ones, reproduce failures (time-travel debugging). Merkle trees (certificate transparency) as future tooling.' }
  ];
})();
